{"command": "cat /workspace/contracts/openapi.contract.json | python3 -c "
import json, sys
c = json.load(sys.stdin)
for path, methods in c['paths'].items():
    for method, details in methods.items():
        if method not in ('get','post','put','patch','delete'):
            continue
        opid = details.get('operationId','?')
        print(f'=== {method.upper()} {path} ({opid}) ===')
        # params
        params = details.get('parameters', [])
        if params:
            print('PARAMS:')
            for p in params:
                print(f'  {p.get(\"name\")} in={p.get(\"in\")} required={p.get(\"required\",False)} type={p.get(\"schema\",{}).get(\"type\",\"?\")}')
        # request body
        rb = details.get('requestBody',{})
        if rb:
            content = rb.get('content',{}).get('application/json',{})
            schema = content.get('schema',{})
            print('REQUEST BODY:')
            print(json.dumps(schema, indent=2))
        # responses
        print('RESPONSES:')
        for code, resp in details.get('responses',{}).items():
            content = resp.get('content',{}).get('application/json',{})
            schema = content.get('schema',{})
            if schema:
                print(f'  {code}: {json.dumps(schema)[:200]}')
            else:
                print(f'  {code}: (no body schema)')
        print()
" 2>&1"}

