type Config struct {
	Port          string
	AdminUsername string
	AdminPassword string
	DatabaseURL   string
	RedisURL      string
	MongoURI      string
}

func Load() *Config {
	cfg := &Config{
		Port: "8080",
		DatabaseURL: "postgres://postgres:postgres@127.0.0.1:5432/lab_samples?sslmode=disable",
		RedisURL:    "redis://127.0.0.1:6379/0",
		MongoURI:    "mongodb://127.0.0.1:27017/arena",
	}

	if v := os.Getenv("PORT"); v != "" {
		cfg.Port = v
	}
	if v := os.Getenv("DATABASE_URL"); v != "" {
		cfg.DatabaseURL = v
	}
	if v := os.Getenv("ADMIN_USERNAME"); v != "" {
		cfg.AdminUsername = v
	}
	if v := os.Getenv("ADMIN_PASSWORD"); v != "" {
		cfg.AdminPassword = v
