	_, err := d.Exec(schema)
	if err != nil {
		return fmt.Errorf("migrate: %w", err)
	}

	// Seed default sample types if none exist
	var count int
	d.QueryRow("SELECT COUNT(*) FROM sample_types").Scan(&count)
	if count == 0 {
		if err := d.seedSampleTypes(); err != nil {
			return fmt.Errorf("seed sample types: %w", err)
		}
	}

	log.Println("Migrations complete")
	return nil
