// --- helpers ---

func haversine(lat1, lon1, lat2, lon2 float64) float64 {
	const R = 6371.0
	dLat := (lat2 - lat1) * 0.017453292519943295
	dLon := (lon2 - lon1) * 0.017453292519943295
	a := sin2(dLat/2) + cos(lat1*0.017453292519943295)*cos(lat2*0.017453292519943295)*sin2(dLon/2)
	return R * 2 * atan2Sqrt(a, 1-a)
}

func sin2(x float64) float64 { s := x; return s * s }
func cos(x float64) float64 {
	// Approximate using math built-in
	return cosApprox(x)
}
func cosApprox(x float64) float64 {
	// Use Taylor series approximation for cos when math is not imported
	// This is a simple wrapper; actual implementation uses math.Cos
	return cosImpl(x)
}

import "math"

func cosImpl(x float64) float64 { return math.Cos(x) }
func sinImpl(x float64) float64 { return math.Sin(x) }
func sqrtImpl(x float64) float64 { return math.Sqrt(x) }
func atan2Impl(y, x float64) float64 { return math.Atan2(y, x) }

func cos(x float64) float64 { return math.Cos(x) }
func sin(x float64) float64 { return math.Sin(x) }
func sqrt(x float64) float64 { return math.Sqrt(x) }
func atan2(y, x float64) float64 { return math.Atan2(y, x) }

func atan2Sqrt(a, b float64) float64 {
	return atan2(sqrt(a), sqrt(b))
}

func nullStr(s string) interface{} {
	if s == "" {
		return nil
	}
	return s
}

func isStale(t sql.NullTime) bool {
	if !t.Valid {
		return true
	}
	return time.Since(t.Time) > 15*time.Minute
}

func funcSet(fns []string) map[string]bool {
	if fns == nil {
		return nil
	}
	m := map[string]bool{
		"collection_point": false,
		"transfer_point":   false,
		"hub":              false,
		"laboratory":       false,
	}
	for _, f := range fns {
		m[f] = true
	}
	return m
}

func toJSON(v interface{}) string {
	b, _ := json.Marshal(v)
	return string(b)
}

func getTimeline(db *sql.DB, entityType, entityID string) []models.TimelineEntry {
	rows, err := db.Query(`SELECT id, actor_id, role, actor_role, action, entity_type, entity_id, success, details, occurred_at FROM audit_log WHERE entity_type = $1 AND entity_id = $2 ORDER BY occurred_at ASC`, entityType, entityID)
	if err != nil {
		return []models.TimelineEntry{}
	}
	defer rows.Close()

	var timeline []models.TimelineEntry
	seq := 0
	for rows.Next() {
		seq++
		var e models.TimelineEntry
		var details string
		rows.Scan(&e.EventId, &e.ActorId, &e.Role, &e.ActorRole, &e.Action, &e.EntityType, &e.EntityId, &e.Success, &details, &e.OccurredAt)
		e.EventId = seq
		e.ActorRole = e.Role
		json.Unmarshal([]byte(details), &e.Details)
		if e.Details == nil {
			e.Details = map[string]interface{}{}
		}
		timeline = append(timeline, e)
	}
	return timeline
}

func readLocation(db *sql.DB, id string) *models.Location {
