	}
	middleware.WriteData(w, 200, map[string]interface{}{
		"version":               1,
		"activeCollectionNodes": len(region),
		"region":                region,
	})
}

func (h *Handler) audit(userID, role, action, entityType, entityID string, success bool, details map[string]interface{}) {
	if details == nil {
