func (h *Handler) SetLocationFunctionStatus(w http.ResponseWriter, r *http.Request) {
	userID := middleware.GetUserID(r.Context())
	activeRole := middleware.GetActiveRole(r.Context())
	if activeRole != models.RoleAdministrator {
		middleware.WriteError(w, 403, "Forbidden", "forbidden")
		return
	}
	var req struct {
		LocationId string `json:"locationId"`
		Function   string `json:"function"`
		Active     bool   `json:"active"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		middleware.WriteError(w, 400, "Invalid JSON", "invalid_json")
		return
	}

	col := ""
	switch req.Function {
	case "collection_point":
		col = "collection_point"
	case "transfer_point":
		col = "transfer_point"
	case "hub":
		col = "hub"
	case "laboratory":
		col = "laboratory"
	default:
		middleware.WriteError(w, 400, "Invalid function", "invalid_json")
		return
	}
	h.DB.Exec("UPDATE locations SET "+col+" = $2, updated_at = NOW() WHERE id = $1", req.LocationId, req.Active)
	_ = userID
	middleware.WriteData(w, 200, map[string]interface{}{"locationId": req.LocationId, "function": req.Function, "active": req.Active})
}

