{"command": "create", "file_text": "import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { api } from '../services/api';
import type { BootstrapData, ServiceabilityResponse } from '../types/models';

export default function NewRequest() {
  const navigate = useNavigate();
  const [bootstrap, setBootstrap] = useState<BootstrapData | null>(null);
  const [originType, setOriginType] = useState('home');
  const [lat, setLat] = useState('');
  const [lon, setLon] = useState('');
  const [address, setAddress] = useState('');
  const [sampleTypeId, setSampleTypeId] = useState('');
  const [collStart, setCollStart] = useState('');
  const [collEnd, setCollEnd] = useState('');
  const [deadline, setDeadline] = useState('');
  const [svcResult, setSvcResult] = useState<ServiceabilityResponse | null>(null);
  const [checking, setChecking] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');

  useEffect(() => {
    api.readBootstrap().then(setBootstrap).catch(() => {});
  }, []);

  const checkSvc = async () => {
    if (!lat || !lon || !sampleTypeId) {
      setError('Location and sample type required');
      return;
    }
    setChecking(true);
    setError('');
    try {
      const res = await api.checkServiceability({
        origin_latitude: parseFloat(lat),
        origin_longitude: parseFloat(lon),
        origin_type: originType,
        sample_type_id: sampleTypeId,
        delivery_deadline: deadline || undefined,
      });
      setSvcResult(res);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Check failed');
    } finally {
      setChecking(false);
    }
  };

  const submit = async () => {
    if (!svcResult?.serviceable) { setError('Location not serviceable'); return; }
    setSubmitting(true);
    setError('');
    try {
      await api.createCollectionRequest({
        origin_type: originType,
        origin_address: originType !== 'home' ? address : undefined,
        origin_latitude: parseFloat(lat),
        origin_longitude: parseFloat(lon),
        sample_type_id: sampleTypeId,
        collection_window_start: collStart,
        collection_window_end: collEnd,
        delivery_deadline: deadline,
      });
      setSuccess('Request created!');
      setTimeout(() => navigate('/'), 1500);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed');
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <div>
      <h1 className="page-title">New Collection Request</h1>

      {error && <div className="error-msg">{error}</div>}
      {success && <div className="success-msg">{success}</div>}

      <div className="card" style={{ maxWidth: 600 }}>
        <div className="form-group">
          <label>Origin Type</label>
          <select value={originType} onChange={(e) => setOriginType(e.target.value)}>
            <option value="home">Home</option>
            <option value="clinic">Clinic</option>
            <option value="node">Collection Node</option>
          </select>
        </div>

        {originType !== 'home' && (
          <div className="form-group">
            <label>Address</label>
            <input value={address} onChange={(e) => setAddress(e.target.value)} placeholder="Clinic or node address" />
          </div>
        )}

        <div className="grid grid-2">
          <div className="form-group">
            <label>Latitude</label>
            <input type="number" step="any" value={lat} onChange={(e) => setLat(e.target.value)} placeholder="e.g. 51.5074" />
          </div>
          <div className="form-group">
            <label>Longitude</label>
            <input type="number" step="any" value={lon} onChange={(e) => setLon(e.target.value)} placeholder="e.g. -0.1278" />
          </div>
        </div>

        <div className="form-group">
          <label>Sample Type</label>
          <select value={sampleTypeId} onChange={(e) => setSampleTypeId(e.target.value)}>
            <option value="">-- Select --</option>
            {bootstrap?.sample_types?.map((st) => (
              <option key={st.id} value={st.id}>{st.name}</option>
            ))}
          </select>
        </div>

        <div className="grid grid-2">
          <div className="form-group">
            <label>Collection Start</label>
            <input type="datetime-local" value={collStart} onChange={(e) => setCollStart(e.target.value)} />
          </div>
          <div className="form-group">
            <label>Collection End</label>
            <input type="datetime-local" value={collEnd} onChange={(e) => setCollEnd(e.target.value)} />
          </div>
        </div>

        <div className="form-group">
          <label>Delivery Deadline</label>
          <input type="datetime-local" value={deadline} onChange={(e) => setDeadline(e.target.value)} />
        </div>

        <div className="form-actions">
          <button className="btn" onClick={checkSvc} disabled={checking}>
            {checking ? 'Checking...' : 'Check Serviceability'}
          </button>
        </div>

        {svcResult && (
          <div style={{ marginTop: '1rem', padding: '0.75rem', background: svcResult.serviceable ? '#dcfce7' : '#fee2e2', borderRadius: 'var(--radius)' }}>
            <strong>{svcResult.serviceable ? '✓ Serviceable' : '✗ Not Serviceable'}</strong>
            {svcResult.reason && <p style={{ fontSize: '0.85rem', marginTop: '0.25rem' }}>{svcResult.reason}</p>}
            {svcResult.nearest_node_name && <p style={{ fontSize: '0.85rem' }}>Nearest node: {svcResult.nearest_node_name}</p>}
            {svcResult.serviceable && (
              <div style={{ marginTop: '0.75rem' }}>
                <button className="btn btn-primary" onClick={submit} disabled={submitting}>
                  {submitting ? 'Creating...' : 'Submit Request'}
                </button>
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
}", "path": "/workspace/frontend/src/pages/NewRequest.tsx"}

{"command": "create", "file_text": "import React, { useEffect, useState } from 'react';
import { useParams, Link } from 'react-router-dom';
import { api } from '../services/api';
import type { Sample, TimelineEntry, JourneyPlan } from '../types/models';

export default function SampleDetail() {
  const { id } = useParams<{ id: string }>();
  const [sample, setSample] = useState<Sample | null>(null);
  const [timeline, setTimeline] = useState<TimelineEntry[]>([]);
  const [journey, setJourney] = useState<JourneyPlan | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    if (!id) return;
    Promise.all([
      api.readSampleLifecycle(id),
      api.readSampleState(id),
    ])
      .then(([lc, st]) => {
        setSample(st);
        setTimeline(lc.timeline || []);
        if (st.active_journey_id) {
          api.readJourneyPlan(st.active_journey_id).then(setJourney).catch(() => {});
        }
      })
      .catch((err) => setError(err instanceof Error ? err.message : 'Failed'))
      .finally(() => setLoading(false));
  }, [id]);

  if (loading) return <div className="loading">Loading sample...</div>;
  if (error) return <div className="error-msg">{error}</div>;
  if (!sample) return <div>Sample not found</div>;

  return (
    <div>
      <h1 className="page-title">Sample {sample.id?.slice(0, 12)}</h1>

      <div className="grid grid-2">
        <div className="card">
          <h3>Details</h3>
          <dl style={{ marginTop: '0.75rem', display: 'grid', gap: '0.25rem' }}>
            <dt style={{ fontWeight: 600, fontSize: '0.8rem', color: 'var(--text-muted)' }}>Status</dt>
            <dd><span className={`badge badge-${sample.status === 'collected' ? 'active' : 'pending'}`}>{sample.status}</span></dd>
            <dt style={{ fontWeight: 600, fontSize: '0.8rem', color: 'var(--text-muted)' }}>Type</dt>
            <dd>{sample.sample_type_name || sample.sample_type_id}</dd>
            <dt style={{ fontWeight: 600, fontSize: '0.8rem', color: 'var(--text-muted)' }}>Container</dt>
            <dd>{sample.container_type || '-'}</dd>
            <dt style={{ fontWeight: 600, fontSize: '0.8rem', color: 'var(--text-muted)' }}>Cooling Required</dt>
            <dd>{sample.requires_cooling ? 'Yes' : 'No'}</dd>
            <dt style={{ fontWeight: 600, fontSize: '0.8rem', color: 'var(--text-muted)' }}>Origin</dt>
            <dd>{sample.origin_type} {sample.origin_address ? `- ${sample.origin_address}` : ''}</dd>
            <dt style={{ fontWeight: 600, fontSize: '0.8rem', color: 'var(--text-muted)' }}>Deadline</dt>
            <dd>{sample.delivery_deadline ? new Date(sample.delivery_deadline).toLocaleString() : '-'}</dd>
            <dt style={{ fontWeight: 600, fontSize: '0.8rem', color: 'var(--text-muted)' }}>Current Holder</dt>
            <dd>{sample.current_holder_name || 'None'} {sample.location_stale ? '(stale)' : ''}</dd>
            <dt style={{ fontWeight: 600, fontSize: '0.8rem', color: 'var(--text-muted)' }}>Last Update</dt>
            <dd>{sample.last_update ? new Date(sample.last_update).toLocaleString() : '-'}</dd>
          </dl>
        </div>

        <div className="card">
          <h3>Status Timeline</h3>
          <div className="status-timeline" style={{ marginTop: '0.75rem' }}>
            {timeline.map((e, i) => (
              <div key={i} className="timeline-entry">
                <div style={{ fontWeight: 600 }}>{e.status}</div>
                <div style={{ fontSize: '0.8rem', color: 'var(--text-muted)' }}>
                  {new Date(e.timestamp).toLocaleString()}
                </div>
                {e.location && <div style={{ fontSize: '0.85rem' }}>{e.location}</div>}
                {e.actor && <div style={{ fontSize: '0.8rem', color: 'var(--text-muted)' }}>{e.actor}</div>}
              </div>
            ))}
            {timeline.length === 0 && <p style={{ color: 'var(--text-muted)' }}>No timeline entries</p>}
          </div>
        </div>
      </div>

      {journey && (
        <div className="card" style={{ marginTop: '1rem' }}>
          <h3>Journey Plan ({journey.status})</h3>
          <table style={{ marginTop: '0.75rem' }}>
            <thead>
              <tr>
                <th>#</th>
                <th>Location</th>
                <th>Action</th>
                <th>Assigned To</th>
                <th>Status</th>
                <th>Planned Arrival</th>
              </tr>
            </thead>
            <tbody>
              {journey.stops?.map((s) => (
                <tr key={s.id}>
                  <td>{s.sequence}</td>
                  <td>{s.location_name || s.location_id}</td>
                  <td>{s.action}</td>
                  <td>{s.assigned_name || '-'}</td>
                  <td><span className={`badge badge-${s.status === 'completed' ? 'completed' : 'pending'}`}>{s.status}</span></td>
                  <td>{s.planned_arrival ? new Date(s.planned_arrival).toLocaleString() : '-'}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      {sample.handling_checkpoints && sample.handling_checkpoints.length > 0 && (
        <div className="card" style={{ marginTop: '1rem' }}>
          <h3>Handling Checkpoints</h3>
          <table style={{ marginTop: '0.75rem' }}>
            <thead>
              <tr>
                <th>Time</th>
                <th>Container</th>
                <th>Temperature</th>
                <th>Status</th>
              </tr>
            </thead>
            <tbody>
              {sample.handling_checkpoints.map((cp) => (
                <tr key={cp.id}>
                  <td>{new Date(cp.recorded_at).toLocaleString()}</td>
                  <td>{cp.container_type}</td>
                  <td>{cp.temperature != null ? `${cp.temperature}°C` : '-'}</td>
                  <td>{cp.out_of_range ? <span className="badge badge-inactive">Out of Range</span> : <span className="badge badge-completed">OK</span>}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
