{"command": "create", "file_text": "package handlers

import (
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"sync"
	"time"

	"github.com/lab-sample-pickup-delivery/backend/internal/middleware"
)

// SSEEvent is a real-time event for SSE streaming
type SSEEvent struct {
	ID         string      `json:"id"`
	Type       string      `json:"type"`
	EntityType string      `json:"entityType"`
	EntityID   string      `json:"entityId"`
	Payload    interface{} `json:"payload"`
	CreatedAt  time.Time   `json:"createdAt"`
}

// SSEBroker manages SSE client connections and event broadcasting
type SSEBroker struct {
	mu         sync.RWMutex
	clients    map[string]chan SSEEvent
	nextID     int64
	globalChan chan SSEEvent
}

var broker = &SSEBroker{
	clients:    make(map[string]chan SSEEvent),
	globalChan: make(chan SSEEvent, 256),
}

func init() {
	go broker.broadcast()
}

func (b *SSEBroker) broadcast() {
	for ev := range b.globalChan {
		b.mu.RLock()
		for _, ch := range b.clients {
			select {
			case ch <- ev:
			default:
			}
		}
		b.mu.RUnlock()
	}
}

func (b *SSEBroker) subscribe() (string, chan SSEEvent) {
	ch := make(chan SSEEvent, 64)
	b.mu.Lock()
	b.nextID++
	id := fmt.Sprintf("sub_%d", b.nextID)
	b.clients[id] = ch
	b.mu.Unlock()
	return id, ch
}

func (b *SSEBroker) unsubscribe(id string) {
	b.mu.Lock()
	if ch, ok := b.clients[id]; ok {
		delete(b.clients, id)
		close(ch)
	}
	b.mu.Unlock()
}

// PublishEvent publishes an event to all SSE clients
func PublishEvent(ev SSEEvent) {
	select {
	case broker.globalChan <- ev:
	default:
		log.Printf("SSE broker channel full, dropping event: %s", ev.ID)
	}
}

// publishEventFromAudit publishes events from an audit entry
func publishEventFromAudit(actorID, role, action, entityType, entityID string, success bool, details map[string]interface{}) {
	ev := SSEEvent{
		ID:         fmt.Sprintf("evt_%d", time.Now().UnixNano()),
		Type:       action,
		EntityType: entityType,
		EntityID:   entityID,
		Payload: map[string]interface{}{
			"actorId": actorID,
			"role":    role,
			"success": success,
			"details": details,
		},
		CreatedAt: time.Now(),
	}
	PublishEvent(ev)
}

// StreamRealtimeEvents handles SSE streaming endpoint
func (h *Handler) StreamRealtimeEvents(w http.ResponseWriter, r *http.Request) {
	// Authenticate via Bearer [REDACTED] AuthMiddleware is bypassed for GET /api/events
	token := r.Header.Get("Authorization")
	if token == "" || len(token) < 8 || token[:7] != "Bearer " {
		middleware.WriteError(w, 401, "Missing Authorization header", "unauthorized")
		return
	}

	userID, _, _, err := h.Auth.ValidateSession(token[7:])
	if err != nil {
		middleware.WriteError(w, 401, "Invalid session", "unauthorized")
		return
	}
	if userID == "" {
		middleware.WriteError(w, 401, "Invalid session", "unauthorized")
		return
	}

	flusher, ok := w.(http.Flusher)
	if !ok {
		middleware.WriteError(w, 500, "Streaming not supported", "internal_error")
		return
	}

	w.Header().Set("Content-Type", "text/event-stream")
	w.Header().Set("Cache-Control", "no-cache")
	w.Header().Set("Connection", "keep-alive")
	w.Header().Set("Access-Control-Allow-Origin", "*")
	w.WriteHeader(200)

	id, ch := broker.subscribe()
	defer broker.unsubscribe(id)

	ctx := r.Context()

	// Send initial connected event
	initial := SSEEvent{
		ID:         fmt.Sprintf("evt_%d", time.Now().UnixNano()),
		Type:       "connected",
		EntityType: "system",
		EntityID:   userID,
		Payload:    map[string]interface{}{"userId": userID},
		CreatedAt:  time.Now(),
	}
	data, _ := json.Marshal(initial)
	fmt.Fprintf(w, "data: %s\n\n", data)
	flusher.Flush()

	for {
		select {
		case <-ctx.Done():
			return
		case ev, ok := <-ch:
			if !ok {
				return
			}
			data, _ := json.Marshal(ev)
			fmt.Fprintf(w, "data: %s\n\n", data)
			flusher.Flush()
		}
	}
}", "path": "/workspace/backend/internal/handlers/sse_handler.go"}

